SELECT percentile_cont(0.75) within GROUP (ORDER BY value) AS seventy_five_percentile FROM labevents WHERE subject_id IN (SELECT subject_id FROM patients WHERE gender = 'F' AND age(CURRENT_DATE, date_trunc('year', birthdate)) = 91) AND hadm_id IN (SELECT hadm_id FROM icustays WHERE first_careunit IN (SELECT name FROM careunits WHERE unit_type = 'ICU')) AND itemid = 10105 AND charttime BETWEEN 0 AND 24;